INSERT IGNORE INTO `produtos` (`id`, `nome`, `tipo`, `area`, `sku`, `ativo`, `duracao_meses`, `recorrente`, `responsavel_pedagogico`, `corpo_docente`, `carga_teorica_presencial`, `carga_teorica_sincrona`, `carga_teorica_assincrona`, `carga_pratica`, `carga_extra`, `comissao_tipo`, `comissao_base`, `comissao_bonus`, `descricao`, `ementa`, `observacoes`, `atualizado_em`) VALUES
  ('prod_curso_de_instrumentacao_capilar', 'Curso de instrumentação Capilar', 'curso_livre', 'Transplante Capilar & Tricologia', 'CURSO_TECNICAS', true, 12, false, NULL, NULL, 8, NULL, NULL, 36, NULL, 'valor', '150.00', '200.00', 'Curso de instrumentação capilar para técnicas de enfermagem. Aula teórica no sábado e prática acompanhada.', 'MÓDULO 1 — Fundamentos do Folículo Capilar\n• Estrutura do folículo capilar\n• Bulbo, matriz, papila e haste do pelo\n• Função das glândulas e musculatura\n• Capacidade regenerativa do folículo\n• Entendimento do crescimento capilar\nMÓDULO 2 — Ciclo Capilar e Fases do Crescimento\n• Fase Anágena (crescimento)\n• Fase Catágena (transição)\n• Fase Telógena (queda)\n• Tempo médio de cada fase\n• Entendimento da queda e renovação capilar\nMÓDULO 3 — Preparação do Paciente\n• Orientações pré-operatórias\n• Higienização e preparo\n• Tempo cirúrgico\n• Organização clínica\n• Fluxo de atendimento\nMÓDULO 4 — Organização do Centro Cirúrgico\n• Montagem da sala\n• Controle de materiais\n• Esterilização\n• Preparação da bancada\n• Organização da equipe\nMÓDULO 5 — Equipe e Funções na Cirurgia\n• Função do médico\n• Planejamento cirúrgico\n• Extração e implantação\n• Função dos instrumentadores\n• Acompanhamento do paciente\nMÓDULO 6 — Instrumentais e Materiais\n• Lâminas de implantação\n• Implanters\n• Cabos e lâminas blend\n• Materiais de bancada\n• Soluções e preparo cirúrgico\nMÓDULO 7 — Técnicas de Implantação\n• Separação dos fios\n• Contagem e organização\n• Implantação manual\n• Técnicas delicadas de inserção\n• Cuidados para preservação folicular\nMÓDULO 8 — Biossegurança e Pós-Operatório\n• Cuidados com assepsia\n• Controle de contaminação\n• Descarte correto de materiais\n• Orientações pós-procedimento\n• Recuperação do paciente', NULL, CURRENT_TIMESTAMP(3)),
  ('prod_curso_livre_de_blefaroplastia_superior', 'Curso livre de blefaroplastia Superior', 'curso_livre', 'Pequenas Cirurgias da Face', 'CL002BLEFARO', true, 12, false, 'Dra. Kariza Frantz', NULL, 4, NULL, NULL, 20, NULL, 'valor', '300.00', '450.00', 'Formação prática e intensiva para médicos que querem dominar a blefaroplastia superior com segurança e resultado. Em 3 dias, você tem aula teórica com a especialista, observa cirurgias reais ao vivo e opera pacientes reais com supervisão direta da Dra. Kariza. Turma reduzida de apenas 08 alunos, realizado no Hospital Master. Saia preparado para oferecer o procedimento estético mais realizado no mundo — e recuperar seu investimento com 1 a 2 cirurgias.', 'Datas: 14/15/16 de Agosto\n\nEmenta está em difinição', 'Professora veio através do relacionamento com a Tainara.', CURRENT_TIMESTAMP(3)),
  ('prod_usg_de_mama_e_axila', 'USG de Mama e Axila', 'curso_livre', NULL, 'CURSO-USG', true, 12, false, 'Dra. Lilian Couto', 'Dra. Lilian Couto, Dra. Mariana Mesquita', 4, NULL, NULL, 20, NULL, 'valor', '300.00', '450.00', 'Curso livre presencial de Ultrassonografia de Mama, realizado na Ela Diagnóstico.', NULL, NULL, CURRENT_TIMESTAMP(3)),
  ('prod_master_fue', 'Master FUE', 'curso_livre', NULL, NULL, true, 12, false, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'valor', '450.00', '600.00', NULL, NULL, NULL, CURRENT_TIMESTAMP(3)),
  ('prod_transplante_capilar', 'Transplante Capilar', 'paciente_modelo', 'Transplante Capilar & Tricologia', 'PM001TC', true, 12, false, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'valor', '250.00', '300.00', NULL, NULL, NULL, CURRENT_TIMESTAMP(3)),
  ('prod_transplante_capilar_de_sobrancelha', 'Transplante Capilar de Sobrancelha', 'paciente_modelo', NULL, NULL, true, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'valor', '250.00', '300.00', NULL, NULL, NULL, CURRENT_TIMESTAMP(3)),
  ('prod_transplante_de_barba', 'Transplante de Barba', 'paciente_modelo', 'Transplante Capilar & Tricologia', 'PACIENTE-MODELO-TRANSPLANTE-BARBA', true, 1, false, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'valor', '250.00', '300.00', 'Curso prático de Transplante de Barba', NULL, NULL, CURRENT_TIMESTAMP(3)),
  ('prod_tratamento_capilar', 'Tratamento Capilar', 'paciente_modelo', 'Transplante Capilar & Tricologia', NULL, true, 12, false, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'valor', '20.00', '20.00', NULL, NULL, NULL, CURRENT_TIMESTAMP(3)),
  ('prod_pos_graduacao_em_pequenas_cirurgias_este', 'Pós Graduação em Pequenas Cirurgias Estéticas da Face', 'pos_graduacao', 'Pequenas Cirurgias da Face', 'PG002PCEDF', true, 12, true, 'Leandro Camargo', NULL, 128, 64, 100, 256, 80, 'valor', '0.00', '0.00', 'A Pós-Graduação em Pequenas Cirurgias Estéticas da Face é um programa de especialização de 12 meses voltado para médicos que desejam dominar os procedimentos cirúrgicos faciais de alta demanda e alta lucratividade realizáveis em ambiente ambulatorial. O programa foca em quatro procedimentos-âncora: blefaroplastia superior, blefaroplastia inferior, otomodelação (otoplastia) e lip lift, complementados por procedimentos associados e módulos de gestão, anestesiologia e marketing médico.\n\nO diferencial do IPEMaster é a combinação de teoria robusta com prática real em pacientes, seguindo o modelo já validado na pós de Transplante Capilar e Tricologia. O aluno não assiste — ele opera, sob supervisão direta de cirurgiões com experiência comprovada.', '4. Estrutura do Programa — 12 Meses\nO programa é dividido em 12 módulos mensais, organizados em 3 fases progressivas. Cada módulo tem um encontro presencial (fim de semana) e conteúdo teórico online entre os encontros.\n\nFase 1 — Fundamentos (Meses 1 a 3)\nNesta fase, o aluno constrói a base teórica e anatômica necessária para operar com segurança. Inclui prática em peças anatômicas e simulação.\n\nMódulo 1 — Anatomia Cirúrgica da Face e Anestesiologia \nComponente\nConteúdo\nAnatomia aplicada\nAnatomia topográfica da face: pálpebras, região periorbital, orelha, lábio superior e filtro labial. Planos cirúrgicos, vascularização, inervação e pontos de risco. Anatomia dos coxins de gordura facial.\nAnestesiologia\nAnestesia local e tumescente para cirurgias faciais. Sedação consciente: protocolos, monitorização e farmacologia. Manejo de emergências e complicações anestésicas. Bloqueios regionais da face (supraorbital, infraorbital, mentoniano, auricular).\nPrática\nDissecção em peças anatômicas (fresh frozen). Identificação de estruturas de risco. Técnicas de infiltração anestésica.\n\nMódulo 2 — Planejamento Cirúrgico e Avaliação do Paciente\n\nComponente\nConteúdo\nAvaliação pré-operatória\nAnamnese cirúrgica completa. Exames pré-operatórios. Classificação de risco. Documentação fotográfica padronizada. Consentimento informado.\nPlanejamento\nAnálise facial: proporções, simetria, envelhecimento. Seleção do paciente: indicações e contraindicações. Planejamento cirúrgico individualizado. Simulação digital de resultados.\nAspectos legais\nResponsabilidade médica em cirurgia estética. Documentação defensiva. Prontuário cirúrgico. Aspectos éticos e do CFM.\n\nMódulo 3 — Instrumentação, Ambiente Cirúrgico e Suturas\n\nComponente\nConteúdo\nInstrumentação\nInstrumental cirúrgico para cirurgias faciais: bisturis, tesouras, pinças, afastadores, cautério. Montagem de mesa cirúrgica. Eletrocautério: princípios e aplicação.\nAmbiente ambulatorial\nEstruturação de sala cirúrgica ambulatorial. Normas da ANVISA. Esterilização e biossegurança. Equipe mínima e fluxo operacional.\nSuturas\nTécnicas de sutura: simples, contínua, subdérmica, intradérmica. Materiais de sutura: absorvíveis e não absorvíveis. Prática intensiva de sutura em modelos sintéticos e peças. Princípios de cicatrização e manejo de cicatrizes.\n\nFase 2 — Domínio Técnico (Meses 4 a 9)\nEsta é a fase central do programa. Cada módulo é dedicado a um procedimento específico, com teoria aprofundada seguida de prática cirúrgica real em pacientes, sob supervisão direta.\n\nMódulo 4 — Blefaroplastia Superior: Teoria e Técnica\n\nComponente\nConteúdo\nTeoria\nAnatomia palpebral superior detalhada. Fisiopatologia da dermatocálase. Indicações e contraindicações. Marcação cirúrgica: técnicas e armadilhas. Variações técnicas: pele, músculo, gordura.\nTécnica cirúrgica\nPasso a passo da blefaroplastia superior. Ressecção de pele, orbicular e gordura. Hemostasia. Suturas palpebrais. Curativos e pós-operatório imediato.\nComplicações\nHematoma, lagoftalmo, assimetria, ptose, olho seco, cicatriz inestética. Prevenção e manejo.\n\nMódulo 5 — Blefaroplastia Superior: Prática Cirúrgica\n\nComponente\nConteúdo\nPrática\nCada aluno realiza blefaroplastia superior em pacientes reais sob supervisão direta. Marcação, anestesia, incisão, ressecção, hemostasia e sutura. Discussão intraoperatória de decisões técnicas.\nPós-operatório\nAcompanhamento do pós-operatório dos pacientes operados. Manejo de edema, equimose e orientações ao paciente. Avaliação de resultado precoce.\n\nMódulo 6 — Blefaroplastia Inferior: Teoria e Técnica\n\nComponente\nConteúdo\nTeoria\nAnatomia palpebral inferior: septo, gordura, músculo, pele. Fisiopatologia das bolsas palpebrais e do sulco nasojugal. Indicações: via transcutânea vs. transconjuntival. Técnicas: pinch, skin flap, fat repositioning.\nTécnica cirúrgica\nBlefaroplastia inferior transcutânea: passo a passo. Blefaroplastia inferior transconjuntival. Reposicionamento de gordura vs. ressecção. Cantopexia e cantoplastia quando indicadas.\nComplicações\nEctrópio, scleral show, hematoma retrobulbar (emergência), assimetria, olho seco. Prevenção e manejo de urgência.\n\nMódulo 7 — Blefaroplastia Inferior: Prática Cirúrgica\n\nComponente\nConteúdo\nPrática\nCada aluno realiza blefaroplastia inferior em pacientes reais sob supervisão direta. Escolha da via de acesso conforme caso. Manejo intraoperatório de gordura e pele.\nCasos combinados\nBlefaroplastia superior + inferior no mesmo tempo cirúrgico. Discussão de indicações de combinação. Planejamento integrado.\n\nMódulo 8 — Otomodelação (Otoplastia): Teoria e Prática\n\nComponente\nConteúdo\nTeoria\nAnatomia da orelha: cartilagem, pericôndrio, pele, vascularização. Classificação das deformidades auriculares. Técnicas: Mustardé, Furnas, Converse, técnicas combinadas. Otomodelação: abordagem minimamente invasiva.\nTécnica cirúrgica\nPasso a passo da otoplastia clássica. Otomodelação com pontos de modelagem. Ressecção de cartilagem vs. modelagem. Curativos e contenção.\nPrática\nCada aluno realiza otoplastia/otomodelação em pacientes reais. Discussão de variações anatômicas e adaptação técnica.\nComplicações\nHematoma, infecção de cartilagem (condrite), assimetria, recidiva, quelóide. Prevenção e manejo.\n\nMódulo 9 — Lip Lift: Teoria e Prática\n\nComponente\nConteúdo\nTeoria\nAnatomia do lábio superior: filtro labial, vermelhão, músculo orbicular, vascularização. Proporções faciais e labiais ideais. Indicações: envelhecimento, filtro longo, perda de show do vermelhão. Técnicas: lip lift direto (subnasal bullhorn), lip lift indireto, corner lift.\nTécnica cirúrgica\nLip lift subnasal (bullhorn): marcação, incisão, ressecção, sutura. Lip lift indireto: técnica e indicações. Corner lift: técnica para comissura labial. Cicatriz: como minimizar e posicionar na junção nasolabial.\nPrática\nCada aluno realiza lip lift em pacientes reais sob supervisão direta. Marcação precisa e execução. Discussão de variações de técnica conforme anatomia do paciente.\nComplicações\nCicatriz visível, assimetria, parestesia, necrose de retalho. Prevenção e manejo.\n\nFase 3 — Integração e Autonomia (Meses 10 a 12)\nNesta fase final, o aluno consolida a prática, opera com maior autonomia e se prepara para atuar de forma independente.\n\nMódulo 10 — Procedimentos Complementares e Combinações\n\nComponente\nConteúdo\nProcedimentos complementares\nBrowlift (lifting de supercílio): técnicas minimamente invasivas. Lobuloplastia (reparo de lóbulo de orelha). Castanhares (xantelasma). Alectomia (redução de asa nasal). Remoção de lesões faciais (cistos, lipomas, nevos).\nCombinações cirúrgicas\nBlefaro superior + inferior. Blefaro + browlift. Lip lift + blefaro. Otoplastia bilateral. Planejamento de múltiplos procedimentos no mesmo tempo cirúrgico.\n\nMódulo 11 — Pós-Operatório Avançado, Complicações e Revisões\n\nComponente\nConteúdo\nPós-operatório avançado\nProtocolos de pós-operatório por procedimento. Terapias adjuvantes: laser, LED, microagulhamento para cicatrizes. Manejo de expectativas do paciente. Acompanhamento de longo prazo.\nComplicações\nRevisão sistemática de complicações por procedimento. Manejo de emergências: hematoma retrobulbar, comprometimento vascular. Cirurgias de revisão: quando e como. Discussão de casos complicados.\n\nMódulo 12 — Gestão, Marketing Médico e Prática Supervisionada Final\n\nComponente\nConteúdo\nGestão e marketing\nEstruturação de consultório para cirurgias ambulatoriais. Precificação de procedimentos cirúrgicos. Marketing médico ético: posicionamento, conteúdo, captação. Gestão financeira da prática cirúrgica.\nPrática final\nCada aluno realiza procedimentos com supervisão mínima (autonomia assistida). Avaliação prática final. Discussão de portfólio de casos.\nEncerramento\nApresentação de casos operados durante o programa. Certificação. Plano de ação individual para início da prática independente.', NULL, CURRENT_TIMESTAMP(3)),
  ('prod_pos_graduacao_lato_sensu_transplante_cap', 'Pós-Graduação Lato Sensu - Transplante Capilar e Tricologia', 'pos_graduacao', 'Transplante Capilar & Tricologia', 'PG001TCT', true, 12, true, NULL, 'Dr. Leandro Camargo, Dra. Ellen Neto , Dra. Fernanda Ferolla, Dra. Mariana Telles', 52, 60, 150, 350, 360, 'valor', '650.00', '1000.00', 'Tornar o médico um especialista completo em medicina capilar — da tricologia clínica ao transplante cirúrgico — com as mais horas práticas do mercado, dentro de um ambiente hospitalar real de referência nacional.', 'Módulo 01\nIntrodução à Medicina Capilar\nMódulo 02\nDiagnóstico e Tratamento de Alopecias\nMódulo 03\nPrincipais Patologias dos Cabelos e do Couro Cabeludo\nMódulo 04\nExames Fundamentais na Tricologia\nMódulo 05\nConsulta e Avaliação Personalizada do Transplante Capilar\nMódulo 06\nPrática de Transplante Capilar\nMódulo 07\nComo Montar sua Clínica e Consultório de Sucesso\nMódulo 08\nInterpretação de Exames\nMódulo 09\nEmergências Clínicas\nMódulo 10\nVivência no Ambulatório Perioperatório\nMódulo 11\nMarketing Médico\nMódulo 12\nSedação Consciente\nMódulo 13\nSimpósio Nacional\nMódulo 14\nEstágio Prático', NULL, CURRENT_TIMESTAMP(3)),
  ('prod_pos_graduacao_em_psiquiatria_hibrido', 'Pós-Graduação em Psiquiatria Híbrido', 'pos_graduacao', NULL, NULL, true, 12, false, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'percentual', '1.25', '2.50', NULL, NULL, 'Compartilha investimento e leads com a Pós-Graduação em Psiquiatria EAD.', CURRENT_TIMESTAMP(3)),
  ('prod_pos_graduacao_em_psiquiatria_ead', 'Pós-Graduação em Psiquiatria EAD', 'pos_graduacao', NULL, NULL, true, 12, false, NULL, 'Dr. Otaviano Netto', NULL, 48, 312, NULL, NULL, 'percentual', '2.00', '4.00', NULL, NULL, NULL, CURRENT_TIMESTAMP(3));
